#include <random>
#include <cstdio>
#include <cstdlib>
#include <cstring>
const char* pat = "GGGGGGGGAGGAAAAGAGGGAAAAAGAAGAAG";
int n = 32;
int hits=0;
void tm(const char* name, const int* bits){
    bool m=true, mi=true;
    for(int i=0;i<n;i++){ int p=(pat[i]=='G'); if(bits[i]!=p) m=false; if(bits[i]==p) mi=false; }
    if(m){printf("MATCH: %s\n", name); hits++;}
    if(mi){printf("MATCH(inv): %s\n", name); hits++;}
}
template<class E> void test_engine(const char* ename, unsigned long maxseed){
    int bits[64];
    for(unsigned long seed=0; seed<maxseed; seed++){
        { E g(seed); for(int i=0;i<n;i++){ unsigned long long v=g(); bits[i]= v&1; }
          char nm[80]; sprintf(nm,"%s(%lu) lsb",ename,seed); tm(nm,bits);}
        { E g(seed); for(int i=0;i<n;i++){ unsigned long long v=g(); bits[i]= (v>>(E::word_size-1))&1; }
          char nm[80]; sprintf(nm,"%s(%lu) msb",ename,seed); tm(nm,bits);}
        { E g(seed); std::uniform_real_distribution<double> u(0.0,1.0);
          for(int i=0;i<n;i++){ bits[i]= u(g)<0.5; }
          char nm[80]; sprintf(nm,"%s(%lu) unif<0.5",ename,seed); tm(nm,bits);}
        { E g(seed);
          for(int i=0;i<n;i++){ double d=std::generate_canonical<double,53>(g); bits[i]= d<0.5; }
          char nm[80]; sprintf(nm,"%s(%lu) canon<0.5",ename,seed); tm(nm,bits);}
    }
}
int main(){
    test_engine<std::mt19937_64>("mt64", 20000);
    test_engine<std::mt19937>("mt32", 20000);
    test_engine<std::minstd_rand>("minstd", 20000);
    test_engine<std::minstd_rand0>("minstd0", 20000);
    test_engine<std::ranlux24_base>("rl24", 20000);
    test_engine<std::ranlux48_base>("rl48", 20000);
    test_engine<std::knuth_b>("knuth", 20000);
    // drand48 family
    int bits[64];
    for(long seed=0; seed<20000; seed++){
        srand48(seed); for(int i=0;i<n;i++) bits[i]= drand48()<0.5;
        char nm[64]; sprintf(nm,"drand48(%ld)<0.5",seed); tm(nm,bits);
        srand48(seed); for(int i=0;i<n;i++) bits[i]= lrand48()&1;
        sprintf(nm,"lrand48(%ld)&1",seed); tm(nm,bits);
    }
    for(unsigned seed=0; seed<20000; seed++){
        srand(seed); for(int i=0;i<n;i++) bits[i]= rand()&1;
        char nm[64]; sprintf(nm,"rand(%u)&1",seed); tm(nm,bits);
        srand(seed); for(int i=0;i<n;i++) bits[i]= (rand()/(RAND_MAX+1.0))<0.5;
        sprintf(nm,"rand(%u) dbl<0.5",seed); tm(nm,bits);
    }
    printf("done hits=%d\n", hits);
}
EOF
