#include <vector>
std::string PAT;
int N;
bool check(const std::vector<int>& bits){
    for(int i=0;i<N;i++) if(bits[i] != PAT[i]-'0') return false;
    return true;
}
bool check_inv(const std::vector<int>& bits){
    for(int i=0;i<N;i++) if(bits[i] == PAT[i]-'0') return false;
    return true;
}
int main(){
    FILE* f=fopen("/tmp/rb_bits.txt","r"); char buf[8192]; fscanf(f,"%4095s",buf); PAT=buf; N=PAT.size();
    fclose(f);
    int hits=0;
    std::vector<int> bits(N);
    // 1) mt64: seed 0..500, skip 0..1200, bitpos 0..63
    for(unsigned long long seed=0; seed<=500; seed++){
        for(int bitpos=0; bitpos<64; bitpos++){
            // generate enough draws once
            std::mt19937_64 g(seed);
            std::vector<unsigned long long> draws(N+1200);
            for(size_t i=0;i<draws.size();i++) draws[i]=g();
            for(int skip=0; skip<=1200; skip++){
                for(int i=0;i<N;i++) bits[i]=(draws[skip+i]>>bitpos)&1;
                if(check(bits)){printf("MATCH mt64(%llu) skip=%d bitpos=%d\n",seed,skip,bitpos);hits++;}
                if(check_inv(bits)){printf("MATCH(inv) mt64(%llu) skip=%d bitpos=%d\n",seed,skip,bitpos);hits++;}
            }
        }
    }
    printf("phase1 done hits=%d\n",hits);
    // 2) xorshift128+ with splitmix64 seeding
    for(unsigned long long seed=0; seed<=2000; seed++){
        unsigned long long s0,s1;
        { unsigned long long z=seed;
          auto sm=[&](){ z+=0x9E3779B97F4A7C15ULL; unsigned long long x=z; x=(x^(x>>30))*0xBF58476D1CE4E5B9ULL; x=(x^(x>>27))*0x94D049BB133111EBULL; return x^(x>>31); };
          s0=sm(); s1=sm(); }
        unsigned long long a=s0,b=s1;
        for(int i=0;i<N;i++){
            unsigned long long x=a,y=b; a=y; x^=x<<23; b=x^y^(x>>17)^(y>>26);
            unsigned long long v=b+y;
            bits[i]=(v>>63)&1;
        }
        if(check(bits)){printf("MATCH xs128+(sm,%llu) msb\n",seed);hits++;}
        if(check_inv(bits)){printf("MATCH(inv) xs128+(sm,%llu) msb\n",seed);hits++;}
        a=s0;b=s1;
        for(int i=0;i<N;i++){
            unsigned long long x=a,y=b; a=y; x^=x<<23; b=x^y^(x>>17)^(y>>26);
            unsigned long long v=b+y;
            bits[i]=v&1;
        }
        if(check(bits)){printf("MATCH xs128+(sm,%llu) lsb\n",seed);hits++;}
        if(check_inv(bits)){printf("MATCH(inv) xs128+(sm,%llu) lsb\n",seed);hits++;}
    }
    printf("phase2 done hits=%d\n",hits);
}
EOF
