// seqtk gap: report locations of gap runs (any non-ACGT base) per sequence.
// Output columns: name, 0-based start, end (exclusive), tab-separated.
#include <cstdio>
#include <cstdlib>
#include <csignal>
#include <unistd.h>
#include "common.h"

static inline bool is_acgt(char c) {
    switch (c) {
    case 'A': case 'C': case 'G': case 'T':
    case 'a': case 'c': case 'g': case 't':
        return true;
    default:
        return false;
    }
}

int cmd_gap(int argc, char** argv) {
    if (argc == 1) {
        fprintf(stderr, "Usage: seqtk %s [-l 50] <in.fa>\n", argv[0]);
        return 1;
    }
    int c, min_len = 50;
    while ((c = getopt(argc, argv, "l:")) >= 0) {
        if (c == 'l') min_len = atoi(optarg);
    }
    if (optind == argc) {
        // The reference passes a NULL path to gzopen here and crashes with
        // SIGSEGV; reproduce that observable behavior.
        raise(SIGSEGV);
        return 139;
    }
    SeqFile sf(argv[optind]);
    if (!sf.is_open()) {
        fprintf(stderr, "[E::stk_gap] failed to open the input file/stream.\n");
        return 1;
    }
    SeqRecord r;
    int ret;
    while ((ret = sf.next(r)) != 0) {
        if (ret < 0) continue; // skip stray bytes up to the next '>'/'@' header
        // kseq rejects FASTQ records whose quality length differs from the
        // sequence length and stops reading the file at that point.
        if (r.is_fastq && r.qual.size() != r.seq.size()) break;
        const std::string& s = r.seq;
        long st = -1;
        for (size_t i = 0; i < s.size(); ++i) {
            if (!is_acgt(s[i])) {
                if (st < 0) st = (long)i;
            } else if (st >= 0) {
                if ((long)i - st >= min_len)
                    printf("%s\t%ld\t%ld\n", r.name.c_str(), st, (long)i);
                st = -1;
            }
        }
        if (st >= 0 && (long)s.size() - st >= min_len)
            printf("%s\t%ld\t%ld\n", r.name.c_str(), st, (long)s.size());
    }
    return 0;
}

