#include <random>
#include <cstdio>
#include <cstring>
#include <string>
#include <cstdlib>
std::string target = "ARRRRRARRAAAAAAAARRRAAAARARRRARRARRRARRAAAAARRRRRARRRRAAARARAAARARAARAAARARARRRAARAARAAAARRAARARARRA";
template<class E>
void brute(const char* ename, unsigned long long maxseed){
    for (unsigned long long seed = 0; seed < maxseed; ++seed) {
        for (int skip = 0; skip < 5; ++skip) {
            for (int mode = 0; mode < 4; ++mode) {
                E g(seed);
                for (int i = 0; i < skip; ++i) g();
                std::string buf;
                for (int i = 0; i < 100; ++i) {
                    unsigned long long x = g();
                    double u = (x>>11) * (1.0/9007199254740992.0);
                    int bit;
                    switch(mode){
                        case 0: bit = u < 0.5; break;
                        case 1: bit = x & 1; break;
                        case 2: bit = (int)(u*2.0); break;
                        default: bit = x % 2; break;
                    }
                    buf += bit ? 'R' : 'A';
                }
                if (buf == target) printf("MATCH %s seed=%llu skip=%d mode=%d\n", ename, seed, skip, mode);
            }
        }
    }
}
int main(){
    brute<std::mt19937_64>("mt64", 300000);
    brute<std::mt19937>("mt32", 300000);
    brute<std::minstd_rand>("minstd", 300000);
    // rand()/srand
    for (unsigned s = 0; s < 300000; ++s) {
        srand(s);
        std::string buf;
        for (int i = 0; i < 100; ++i) buf += (rand() & 1) ? 'R' : 'A';
        if (buf == target) printf("MATCH rand()&1 seed=%u\n", s);
        srand(s);
        buf.clear();
        for (int i = 0; i < 100; ++i) buf += (rand() < RAND_MAX/2) ? 'A' : 'R';
        if (buf == target) printf("MATCH rand()half seed=%u\n", s);
    }
    printf("done\n");
    return 0;
}
