#!/usr/bin/env python3
import subprocess, os, random, gzip, sys

ORIG = "/tmp/orig_seqtk"
MINE = "/tmp/mine_gap"
random.seed(12345)

def run(prog, args, stdin_data=None):
    p = subprocess.run([prog, "gap"] + args, input=stdin_data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.returncode, p.stdout, p.stderr

ALPHA = list("ACGTacgtNnxXUuRYSWKMBDHVryswkmbdhv.- 0123456789!*")

def rand_seq(rng):
    return "".join(rng.choice(ALPHA) for _ in range(rng.randrange(0, 120)))

def rand_fasta(rng):
    out = []
    for _ in range(rng.randrange(0, 6)):
        name = "".join(rng.choice("abcXYZ_012") for _ in range(rng.randrange(0, 8)))
        cmt = "".join(rng.choice("abc \t|") for _ in range(rng.randrange(0, 10)))
        out.append(">" + name + (" " + cmt if rng.random() < 0.5 and cmt else (cmt if rng.random() < 0.3 else "")))
        seq = rand_seq(rng)
        while seq:
            n = rng.randrange(1, 30)
            out.append(seq[:n])
            seq = seq[n:]
        if rng.random() < 0.2:
            out.append("")
    if rng.random() < 0.3:
        out.insert(0, "junk" + rand_seq(rng))
    return ("\n".join(out) + ("\n" if rng.random() < 0.9 else "")).encode()

def rand_fastq(rng):
    out = []
    for _ in range(rng.randrange(1, 5)):
        name = "".join(rng.choice("abcXYZ_012") for _ in range(rng.randrange(0, 8)))
        out.append("@" + name)
        seq = rand_seq(rng)
        out.append(seq)
        out.append("+" + (name if rng.random() < 0.5 else ""))
        qlen = len(seq) + rng.choice([0, 0, 0, 1, -1, 3])
        q = "".join(rng.choice("II#@>") for _ in range(max(0, qlen)))
        while q:
            n = rng.randrange(1, 25)
            out.append(q[:n])
            q = q[n:]
    return ("\n".join(out) + "\n").encode()

fail = 0
total = 0
for i in range(400):
    rng = random.Random(1000 + i)
    data = rand_fasta(rng) if i % 2 == 0 else rand_fastq(rng)
    if rng.random() < 0.2:
        data = gzip.compress(data)
    if rng.random() < 0.2:
        data = data.replace(b"\n", b"\r\n")
    path = f"/tmp/gaptest/fuzz{i}.txt"
    with open(path, "wb") as f:
        f.write(data)
    args = []
    r = rng.random()
    if r < 0.3:
        pass
    elif r < 0.6:
        args += ["-l", str(rng.randrange(-2, 60))]
    elif r < 0.8:
        args += ["-l" + str(rng.randrange(0, 10))]
    else:
        args += ["-l", str(rng.randrange(0, 5))]
    if rng.random() < 0.1:
        args = ["-z"] + args
    args.append(path)
    r1 = run(ORIG, args)
    r2 = run(MINE, args)
    total += 1
    if r1 != r2:
        fail += 1
        print(f"MISMATCH fuzz{i} args={args} data={data!r}")
        print(f"  orig: rc={r1[0]} out={r1[1]!r} err={r1[2]!r}")
        print(f"  mine: rc={r2[0]} out={r2[1]!r} err={r2[2]!r}")
        if fail > 5:
            break

print(f"{total} fuzz cases, {fail} mismatches")
sys.exit(1 if fail else 0)

