#include <cstdio>
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
std::string PAT; int N;
bool check(const std::vector<int>& bits){ for(int i=0;i<N;i++) if(bits[i]!=PAT[i]-'0') return false; return true; }
bool check_inv(const std::vector<int>& bits){ for(int i=0;i<N;i++) if(bits[i]==PAT[i]-'0') return false; return true; }
static inline uint64_t sm64(uint64_t &x){ uint64_t z=(x+=0x9E3779B97F4A7C15ULL); z=(z^(z>>30))*0xBF58476D1CE4E5B9ULL; z=(z^(z>>27))*0x94D049BB133111EBULL; return z^(z>>31); }
static inline uint64_t rotl(uint64_t x,int k){ return (x<<k)|(x>>(64-k)); }
int main(){
    FILE* f=fopen("/tmp/rb_bits.txt","r"); char buf[8192]; if(fscanf(f,"%4095s",buf)!=1) return 1; PAT=buf; N=PAT.size(); fclose(f);
    int hits=0; std::vector<int> bits(N);
    for(uint64_t seed=0; seed<=5000; seed++){
        // xoroshiro128+ (2016 variant: rotl 55,14,36)
        for(int variant=0; variant<3; variant++){
            uint64_t s[2]; { uint64_t x=seed; s[0]=sm64(x); s[1]=sm64(x); }
            std::vector<uint64_t> outs(N+8);
            uint64_t s0=s[0],s1=s[1];
            for(int i=0;i<N;i++){
                uint64_t r;
                if(variant==0){ r=s0+s1; uint64_t t=s1^s0; s0=rotl(s0,55)^t^(t<<14); s1=rotl(t,36); }
                else if(variant==1){ r=s0+s1; uint64_t t=s1^s0; s0=rotl(s0,24)^t^(t<<16); s1=rotl(t,37); } // xoroshiro128+ v1.0
                else { uint64_t x=s0,y=s1; s0=y; x^=x<<23; s1=x^y^(x>>17)^(y>>26); r=s1+y; } // xorshift128+
                outs[i]=r;
            }
            for(int bp=0; bp<64; bp++){
                for(int i=0;i<N;i++) bits[i]=(outs[i]>>bp)&1;
                if(check(bits)){printf("MATCH var%d seed=%llu bp=%d\n",variant,(unsigned long long)seed,bp);hits++;}
                if(check_inv(bits)){printf("MATCH(inv) var%d seed=%llu bp=%d\n",variant,(unsigned long long)seed,bp);hits++;}
            }
            // (v>>11)*2^-53 < 0.5 == bp 63, covered. also v*2^-64<0.5 same.
        }
        // alternate seeding: s0=seed, s1=splitmix(seed)
        {
            uint64_t x=seed; uint64_t s0=seed, s1=sm64(x);
            std::vector<uint64_t> outs(N);
            for(int i=0;i<N;i++){ uint64_t r=s0+s1; uint64_t t=s1^s0; s0=rotl(s0,55)^t^(t<<14); s1=rotl(t,36); outs[i]=r; }
            for(int bp=0;bp<64;bp++){ for(int i=0;i<N;i++) bits[i]=(outs[i]>>bp)&1;
                if(check(bits)) printf("MATCH xorro altseed seed=%llu bp=%d\n",(unsigned long long)seed,bp);
                if(check_inv(bits)) printf("MATCH(inv) xorro altseed seed=%llu bp=%d\n",(unsigned long long)seed,bp); }
        }
    }
    printf("done hits=%d\n",hits);
}
