#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <random>
std::string PAT; int N;
int hits=0;
void trybits(const char* nm, std::vector<int>& bits){
    bool m=true,mi=true;
    for(int i=0;i<N;i++){ if(bits[i]!=PAT[i]-'0') m=false; if(bits[i]==PAT[i]-'0') mi=false; if(!m&&!mi) return; }
    if(m){printf("MATCH %s\n",nm);hits++;} else {printf("MATCH(inv) %s\n",nm);hits++;}
}
int main(){
    FILE* f=fopen("/tmp/rb_bits.txt","r"); char buf[8192]; if(fscanf(f,"%4095s",buf)!=1) return 1; PAT=buf; N=PAT.size(); fclose(f);
    std::vector<int> bits(N);
    char nm[128];
    // stride search on mt64
    for(unsigned long long seed=0; seed<=200; seed++){
        std::mt19937_64 g(seed);
        std::vector<unsigned long long> draws(N*4+300);
        for(size_t i=0;i<draws.size();i++) draws[i]=g();
        for(int stride=1; stride<=4; stride++) for(int off=0; off<stride; off++)
          for(int skip=0; skip<=128; skip++) for(int bp=0; bp<64; bp++){
            for(int i=0;i<N;i++) bits[i]=(draws[skip+(size_t)i*stride+off]>>bp)&1;
            sprintf(nm,"mt64(%llu) stride%d off%d skip%d bp%d",seed,stride,off,skip,bp);
            trybits(nm,bits);
          }
    }
    printf("phase A done %d\n",hits);
    // one draw per 64 bases, use successive bits
    for(unsigned long long seed=0; seed<=2000; seed++){
        std::mt19937_64 g(seed);
        std::vector<unsigned long long> draws(N/64+2);
        for(size_t i=0;i<draws.size();i++) draws[i]=g();
        for(int dir=0;dir<2;dir++){
            for(int i=0;i<N;i++){ int j= dir? 63-(i%64) : i%64; bits[i]=(draws[i/64]>>j)&1; }
            sprintf(nm,"mt64(%llu) bitstream dir%d",seed,dir);
            trybits(nm,bits);
        }
    }
    printf("phase B done %d\n",hits);
    // rand_r
    for(unsigned seed=0; seed<=2000; seed++){
        unsigned s=seed;
        for(int i=0;i<N;i++) bits[i]=rand_r(&s)&1;
        sprintf(nm,"rand_r(%u)&1",seed); trybits(nm,bits);
        s=seed;
        for(int i=0;i<N;i++) bits[i]=(rand_r(&s)/(RAND_MAX+1.0))<0.5;
        sprintf(nm,"rand_r(%u)dbl",seed); trybits(nm,bits);
    }
    // random()
    for(unsigned seed=0; seed<=2000; seed++){
        srandom(seed);
        for(int i=0;i<N;i++) bits[i]=random()&1;
        sprintf(nm,"random(%u)&1",seed); trybits(nm,bits);
        srandom(seed);
        for(int i=0;i<N;i++) bits[i]=(random()/(2147483648.0))<0.5;
        sprintf(nm,"random(%u)dbl",seed); trybits(nm,bits);
    }
    // drand48 default state (no srand48)
    {
        for(int i=0;i<N;i++) bits[i]=drand48()<0.5;
        trybits("drand48(default)dbl",bits);
        for(int i=0;i<N;i++) bits[i]=lrand48()&1;
        trybits("lrand48(default)&1 cont",bits);
    }
    printf("done hits=%d\n",hits);
}
EOF
